import { createRouteBuilder } from '@cossackframework/core/routes';

const route = createRouteBuilder({ article: '/articles/:slug', files: '/files/:path{.+}' } as const);
const article: string = route('article', { slug: 'hello world' });
const files: string = route('files', { path: ['reports', 'October 2026.csv'] });
if (article !== '/articles/hello%20world') throw new Error('Article URL was not encoded');
if (files !== '/files/reports/October%202026.csv') throw new Error('Catch-all URL was not encoded');
